function patternMatches(s: string, p: string): boolean {
  const eq = (x: string, c: string) => x === "." || x === c;
  const go = (i: number, j: number): boolean => { // s[0..i) against p[0..j)
    if (j === 0) return i === 0;
    if (p[j - 1] === "*")
      return go(i, j - 2) || (i > 0 && eq(p[j - 2], s[i - 1]) && go(i - 1, j)); // zero copies | one more copy
    return i > 0 && eq(p[j - 1], s[i - 1]) && go(i - 1, j - 1);
  };
  return go(s.length, p.length);
}

