function patternMatches(s: string, p: string): boolean {
  const n = s.length, m = p.length;
  const eq = (x: string, c: string) => x === "." || x === c;
  const dp: boolean[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(false));
  dp[0][0] = true;
  for (let i = 0; i <= n; i++)
    for (let j = 1; j <= m; j++) {
      if (p[j - 1] === "*") {
        dp[i][j] = dp[i][j - 2] || (i > 0 && eq(p[j - 2], s[i - 1]) && dp[i - 1][j]); // zero copies | one more copy
      } else {
        dp[i][j] = i > 0 && eq(p[j - 1], s[i - 1]) && dp[i - 1][j - 1];
      }
    }
  return dp[n][m];
}

