function patternMatches(s: string, p: string): boolean {
  const m = p.length;
  const eq = (x: string, c: string) => x === "." || x === c;
  let prev: boolean[] = [];
  for (let i = 0; i <= s.length; i++) {
    const cur: boolean[] = new Array(m + 1).fill(false);
    cur[0] = i === 0;
    for (let j = 1; j <= m; j++) {
      if (p[j - 1] === "*") cur[j] = cur[j - 2] || (i > 0 && eq(p[j - 2], s[i - 1]) && prev[j]);
      else cur[j] = i > 0 && eq(p[j - 1], s[i - 1]) && prev[j - 1];
    }
    prev = cur;
  }
  return prev[m];
}

